import {icon} from './icons.mjs';
import {vault} from './vault.mjs';
import {demoWorkspace} from './demo.mjs';
import {today,ageOn,memberAge,population,residence,matchesMember,visitState,toCSV,scheduleVisits,addDays,CONDITIONS} from './domain.mjs';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=$('#app'),modal=$('#modal');
let data=null,token='',demo=false,view='home',query='',ownerFilter='',listFilter={},visitFilter='all',language=localStorage.getItem('asha-language')||'en',syncing=false,serverBase=localStorage.getItem('asha-server')||(location.hostname==='appassets.androidplatform.net'?'':location.origin),conflict=null,saveChain=Promise.resolve();
const labels={en:{home:'Overview',households:'Families',members:'Population',care:'Maternal & child care',visits:'Visits',lists:'Smart lists',reports:'Reports',team:'ASHA team',settings:'Settings',today:'Today',more:'More'},hi:{home:'अवलोकन',households:'परिवार',members:'जनसंख्या',care:'मातृ एवं शिशु देखभाल',visits:'दौरे',lists:'सूचियाँ',reports:'रिपोर्ट',team:'आशा टीम',settings:'सेटिंग',today:'आज',more:'अन्य'}};
const t=k=>labels[language][k]||k;
const btn=(label,action,ico='',cls='',attrs='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${ico?icon(ico,17):''}${esc(label)}</button>`;
const navs=[['home','grid'],['households','home'],['members','users'],['care','heart'],['visits','calendar'],['lists','filter'],['reports','file']];
const recs=kind=>data.records.filter(r=>!r.deleted&&(!kind||r.kind===kind)&&(!ownerFilter||r.ownerId===ownerFilter||r.kind==='schedule'));
const find=id=>data.records.find(r=>r.id===id);
const person=id=>find(id)?.data.name||'Member';
const worker=id=>data.users.find(u=>u.id===id)?.name||'ASHA';
const dateText=s=>s?new Date(s+'T12:00:00Z').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'Not recorded';
const count=kind=>recs(kind).length;
const badge=(text,cls='')=>`<span class="badge ${cls}">${esc(text)}</span>`;
const nameAvatar=(name,cls='')=>`<span class="avatar ${cls}">${esc(name.split(' ').slice(0,2).map(s=>s[0]).join(''))}</span>`;
const empty=(title,note,button='')=>`<div class="empty">${icon('leaf',32)}<h3>${esc(title)}</h3><p>${esc(note)}</p>${button}</div>`;
const field=(name,label,type='text',value='',extra='')=>`<div class="field"><label for="f-${name}">${esc(label)}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;
const select=(name,label,options,value='',extra='')=>`<div class="field"><label for="f-${name}">${esc(label)}</label><select id="f-${name}" name="${name}" ${extra}>${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`;}).join('')}</select></div>`;
const note=(name,label,value='')=>`<div class="field full"><label for="f-${name}">${esc(label)}</label><textarea id="f-${name}" name="${name}">${esc(value)}</textarea></div>`;
function toast(message,error=false){const el=document.createElement('div');el.className=`toast${error?' error':''}`;el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),6500);}
function dialog(title,content,footer=''){modal.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close" aria-label="Close">${icon('close',18)}</button></div><div class="modal-body">${content}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}`;if(!modal.open)modal.showModal();}
function form(title,fields,submit,{label='Save record',description=''}={}){dialog(title,`<form id="record-form">${description?`<p class="notice spacer-bottom">${esc(description)}</p><br>`:''}<div class="form-grid">${fields}</div><div id="form-error"></div><div class="modal-foot"><button type="button" class="btn" data-action="close">Cancel</button><button class="btn primary" type="submit">${esc(label)}</button></div></form>`);$('#record-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const f=Object.fromEntries(new FormData(e.target));await submit(f,e.target);modal.close();render();}catch(err){$('#form-error').className='form-error';$('#form-error').textContent=err.message;b.disabled=false;}};}
async function api(endpoint,options={}){if(!serverBase)throw Error('Enter your server address first.');const res=await fetch(serverBase+endpoint,{signal:AbortSignal.timeout(30000),...options,headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`} : {}),...options.headers}});if(!res.ok){let b;try{b=await res.json();}catch{b={error:'Could not contact the server.'};}const e=new Error(b.error);e.status=res.status;e.details=b.details;throw e;}return res.json();}
function snapshot(){return {user:data.user,users:data.users,records:data.records,outbox:data.outbox,lastSync:data.lastSync,savedLists:data.savedLists||[]};}
async function persist(){if(demo)return;const snap=structuredClone(snapshot());saveChain=saveChain.catch(()=>{}).then(()=>vault.save(snap,serverBase));await saveChain;}
async function save(kind,values,existing=null,ownerId){
  const id=existing?.id||crypto.randomUUID(),previous=data.outbox.find(m=>m.id===id),baseVersion=previous?.baseVersion??existing?.version??0;
  const item={id,kind,ownerId:existing?.ownerId||ownerId||data.user.id,data:{...existing?.data,...values},version:baseVersion+1,updatedAt:new Date().toISOString(),deleted:false};
  const previousData=structuredClone(data);
  const index=data.records.findIndex(r=>r.id===id);if(index<0)data.records.push(item);else data.records[index]=item;
  const mutation={id,kind,ownerId:item.ownerId,data:item.data,baseVersion,mutationId:crypto.randomUUID()};
  if(previous)data.outbox.splice(data.outbox.indexOf(previous),1,mutation);else data.outbox.push(mutation);
  if(demo){data.outbox=[];toast('Saved in this demo session');return item;}
  try{await persist();}catch(e){data=previousData;throw Error('Could not save securely on this device. Please free storage and try again.');}
  toast('Saved securely on this device');if(token&&navigator.onLine)setTimeout(()=>sync(),100);return item;
}
async function sync(){if(demo){toast('Demo records stay in this session. Connect a server to share records.');return;}if(syncing||!data)return;if(!token){toast('Sign in again to sync. Your offline changes are saved.',true);return;}syncing=true;renderSync();try{
  while(data.outbox.length){const m=structuredClone(data.outbox[0]);try{const ack=await api('/api/sync',{method:'POST',body:JSON.stringify({mutations:[m]})});const index=data.outbox.findIndex(x=>x.id===m.id);if(index>=0){if(data.outbox[index].mutationId===m.mutationId)data.outbox.splice(index,1);else{data.outbox[index].baseVersion=ack.saved[0].version;data.outbox[index].mutationId=crypto.randomUUID();}}await persist();}catch(e){if(e.status===409&&e.details?.id){conflict={mutation:m,saved:e.details.record};showConflict();}throw e;}}
  const remote=await api('/api/sync');const pendingIds=new Set(data.outbox.map(m=>m.id)),pending=data.records.filter(r=>pendingIds.has(r.id));data.records=[...remote.records.filter(r=>!pendingIds.has(r.id)),...pending];data.users=remote.users;data.user=remote.user;data.lastSync=remote.syncedAt;await persist();render();toast('Workspace synced');
 }catch(e){toast(e.message||'Offline. Your changes are saved for later.',true);}finally{syncing=false;renderSync();}}
function renderSync(){const el=$('#sync-button');if(el){el.disabled=syncing;el.innerHTML=icon('sync',15)+esc(syncing?'Syncing…':data.outbox.length?`Sync (${data.outbox.length})`:'Sync');}}
function showConflict(){const {mutation:m,saved}=conflict;dialog('Review a sync conflict',`<p class="notice amber">This record has a newer saved version. Other unsynced changes remain on this device.</p><h3 class="spacer">Your change</h3><pre class="conflict-json">${esc(JSON.stringify({...m.data,content:undefined},null,2))}</pre><h3>Saved version</h3><pre class="conflict-json">${esc(JSON.stringify({...saved?.data,content:undefined},null,2))}</pre>`,btn('Use saved version','conflict-server')+btn('Keep my reviewed changes','conflict-local','','primary'));}
async function restoreAfterLogin(user){
  const metadata=await vault.metadata();
  if(metadata&&metadata.user.id!==user.id){token='';throw Error('A different worker has an offline workspace on this device. Unlock and remove it in Settings before switching accounts.');}
  let remote=null;if(!user.mustChangePassword)remote=await api('/api/sync');
  form(metadata?'Unlock your offline workspace':'Protect this device',field('offlinePassword','Offline password','password','','required minlength="8" autocomplete="current-password"'),async f=>{
    if(metadata){data=await vault.unlock(f.offlinePassword);data.user=user;if(remote&&!data.outbox.length){data.records=remote.records;data.users=remote.users;data.lastSync=remote.syncedAt;}}
    else{await vault.create(f.offlinePassword);data={user,users:remote?.users||[user],records:remote?.records||[],outbox:[],lastSync:remote?.syncedAt||null};}
    demo=false;await persist();view='home';if(user.mustChangePassword)setTimeout(changePassword,0);else if(data.outbox.length)setTimeout(sync,100);
  },{label:metadata?'Unlock':'Create secure workspace',description:'This separate password encrypts records saved on your device. Use at least 8 characters. Keep it safe: it cannot be recovered. Your sign-in password controls access to the shared server.'});
}
async function renderLogin(){data=null;demo=false;ownerFilter='';token='';vault.lock();let meta=null;try{meta=await vault.metadata();}catch{}
  app.innerHTML=`<div class="login"><section class="login-story"><a class="brand" href="#"><img src="assets/logo.svg" alt="ASHA Saathi logo"><div><strong>ASHA Saathi</strong><small>Your care companion</small></div></a><div><div class="login-art"><img src="assets/logo.svg" width="124" height="124" alt=""></div><h1>Your community.<br>Connected care.</h1><p>A little less paperwork.<br>A little more time for the people who need you.</p></div><p class="story-footer">FAMILIES · HOME VISITS · EVERYDAY CARE</p></section><section class="login-pane"><h2>Welcome to Saathi</h2><p>Your families, follow-ups and reports, together.</p><form id="login-form">${field('server','Workspace server','url',serverBase,'placeholder="https://your-server.example" required')}${field('username','Username','text','','autocomplete="username" required')}${field('password','Password','password','','autocomplete="current-password" required')}<div id="login-error"></div><button class="btn primary" type="submit">Sign in ${icon('arrow',17)}</button></form><div class="row between spacer">${btn('Set up workspace','setup','','ghost sm')}${meta?btn('Unlock offline','unlock','lock','ghost sm'):''}</div><div class="divider">or take a look around</div>${btn('Explore the demo','demo','leaf')}<p class="login-note">Demo records are fictional. A live workspace needs your organisation’s server and an authorised account.</p></section></div>`;
  $('#login-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const f=Object.fromEntries(new FormData(e.target));setServer(f.server);const result=await api('/api/login',{method:'POST',body:JSON.stringify({username:f.username,password:f.password})});token=result.token;await restoreAfterLogin(result.user);}catch(err){$('#login-error').className='form-error';$('#login-error').textContent=err.message;}finally{e.submitter.disabled=false;}};
}
function setServer(value){const u=new URL(value);if(u.protocol!=='https:'&&!(u.protocol==='http:'&&['localhost','127.0.0.1','10.0.2.2'].includes(u.hostname)))throw Error('Use an HTTPS server address.');if(u.username||u.password||u.search||u.hash||!['','/'].includes(u.pathname))throw Error('Enter only the server origin, without credentials, query or path.');serverBase=u.origin;localStorage.setItem('asha-server',serverBase);}
function pageHead(title,subtitle,actions=''){return `<div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="row wrap">${actions}</div></div>`;}
function stat(label,value,detail,ico){return `<div class="stat"><div class="stat-top">${esc(label)}<span class="stat-icon">${icon(ico,17)}</span></div><strong>${value}</strong><small>${esc(detail)}</small></div>`;}
function searchBox(placeholder='Search by name…'){return `<div class="search-field">${icon('search',18)}<input id="page-search" aria-label="Search records" placeholder="${esc(placeholder)}" value="${esc(query)}"></div>`;}
function visitRows(visits){return visits.map(v=>{const m=find(v.data.memberId),state=visitState(v),over=state==='Overdue',parts=new Date(v.data.dueDate+'T12:00:00Z');return `<div class="visit-row"><div class="visit-date"><strong>${parts.getUTCDate()}</strong><small>${parts.toLocaleDateString('en',{month:'short',timeZone:'UTC'})}</small></div><div class="grow"><strong>${esc(person(v.data.memberId))}</strong><p>${esc(v.data.program)} · ${esc(find(m?.data.householdId)?.data.locality||'')}</p></div>${badge(state,over?'red':state==='Completed'?'':'amber')}${btn(state==='Completed'?'View':'Open','edit-visit','chevron','sm',`data-id="${v.id}"`)}</div>`;}).join('');}
function home(){const p=population(recs()),preg=recs('pregnancy').filter(r=>r.data.status==='Active'),visits=recs('visit'),due=visits.filter(v=>v.data.status==='Planned'&&v.data.dueDate<=today()).sort((a,b)=>a.data.dueDate.localeCompare(b.data.dueDate)),completed=visits.filter(v=>v.data.status==='Completed');return `${pageHead(t('home'),'A clear view of your community, one day at a time.',btn('Add family','add-household','plus','primary'))}<div class="welcome"><div><div class="eyebrow">EVERY VISIT MAKES A DIFFERENCE</div><h2>Good to see you, ${esc(data.user.name.split(' ')[0])}.</h2><p>${due.length?`${due.length} follow-ups need your attention. Let’s make sure every family feels cared for.`:'Your next visit starts here. Keep your families connected to care.'}</p></div><div class="welcome-art" aria-hidden="true"><div class="art-circle"></div><img class="art-heart" src="assets/logo.svg" alt=""><div class="art-badge">${icon('check',14)} Here for every family</div><span class="art-star">✦</span></div></div><div class="stats">${stat('Total population',p.total,`${p.Male} male · ${p.Female} female · ${p.Other+p.Unknown} other / unknown`,'users')}${stat('Families registered',count('household'),'Households in your selected area','home')}${stat('Active pregnancies',preg.length,'Connected maternal care','heart')}${stat('Visits to follow up',due.length,`${due.filter(v=>visitState(v)==='Overdue').length} overdue · ${completed.length} completed`,'calendar')}</div><div class="dashboard-columns"><div class="stack"><section class="panel"><div class="panel-head"><div><h2>Today & follow-ups</h2><small class="muted">A little attention goes a long way</small></div>${btn('All visits','nav-visits','arrow','ghost sm')}</div>${due.length?visitRows(due.slice(0,5)):empty('You’re up to date','Add a visit or check upcoming follow-ups.',btn('Plan a visit','add-visit','plus','sm'))}<div class="panel-footer"><span>${due.length} pending follow-ups</span><span>As of ${dateText(today())}</span></div></section><section class="panel"><div class="panel-head"><h2>Recently added families</h2>${btn('View all','nav-households','arrow','ghost sm')}</div>${recs('household').slice(-3).reverse().map(h=>`<div class="visit-row">${nameAvatar(h.data.name,'green')}<div class="grow"><strong>${esc(h.data.name)}</strong><p>${esc(h.data.locality)} · ${recs('member').filter(m=>m.data.householdId===h.id).length} members</p></div>${btn('Open','open-household','chevron','ghost sm',`data-id="${h.id}"`)}</div>`).join('')||empty('Start with a family','Create a household, then add its members.')}</section></div><div class="stack"><section class="panel"><div class="panel-head"><h2>Quick actions</h2>${icon('plus',17)}</div><div class="quick-grid">${[['Add a member','add-member','users'],['Register pregnancy','add-pregnancy','heart'],['Plan a visit','add-visit','calendar'],['Record an event','add-event','file']].map(([l,a,i])=>`<button class="quick" data-action="${a}">${icon(i,21)}<span>${l}</span></button>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Community snapshot</h2>${icon('leaf',18)}</div><div class="panel-body">${[['Children below 5',p.under5,''],['Citizens over 80',p.over80,'sand'],['ABHA not recorded',p.abhaMissing,'light']].map(([l,v,c])=>`<div class="insight-row"><span class="legend-dot ${c}"></span><span>${l}</span><strong>${v}</strong></div>`).join('')}</div><div class="panel-footer">${btn('Explore smart lists','nav-lists','arrow','ghost sm')}</div></section><div class="notice">${icon('shield',17)} Your records stay connected. ${demo?'You’re viewing a fictional demonstration.':data.outbox.length?`${data.outbox.length} change(s) safely saved, waiting to sync.`:'Changes sync securely with your supervisor.'}</div></div></div>`;}
function households(){const rows=recs('household').filter(h=>`${h.data.name} ${h.data.address} ${h.data.locality}`.toLowerCase().includes(query.toLowerCase()));return `${pageHead(t('households'),'Every family has a place. Every member has a record.',btn('Add family','add-household','plus','primary'))}<div class="toolbar">${searchBox('Search families, address or locality…')}${badge(`${rows.length} families`)}</div><div class="cards">${rows.map(h=>`<button class="family-card" data-action="open-household" data-id="${h.id}"><div class="row between"><span class="stat-icon">${icon('home',20)}</span>${badge(h.data.locality)}</div><div><h3>${esc(h.data.name)}</h3><p>${esc(h.data.address)}</p></div><div class="card-bottom"><span>${recs('member').filter(m=>m.data.householdId===h.id).length} members · ${esc(worker(h.ownerId))}</span>${icon('arrow',17)}</div></button>`).join('')}</div>${rows.length?'':empty('No families yet','Create your first household to start building the population register.',btn('Add family','add-household','plus','primary'))}`;}
function memberTable(rows){return `<div class="panel table-scroll"><table><thead><tr><th>Member</th><th>Age / sex</th><th>Family</th><th>Residence</th><th>ABHA</th><th></th></tr></thead><tbody>${rows.map(m=>`<tr><td><button class="link" data-action="open-member" data-id="${m.id}">${esc(m.data.name)}</button><div class="sub">${esc(worker(m.ownerId))}</div></td><td>${memberAge(m)??'—'}${!m.data.dob&&m.data.estimatedAge!==''?' ≈':''} · ${esc(m.data.sex)}</td><td>${esc(find(m.data.householdId)?.data.name||'')}</td><td>${badge(residence(m,data.records),residence(m,data.records)==='Resident'?'':'neutral')}</td><td>${m.data.abha?badge(m.data.abhaStatus||'Recorded'):badge('Not recorded','amber')}</td><td>${btn('Profile','open-member','chevron','ghost sm',`data-id="${m.id}"`)}</td></tr>`).join('')}</tbody></table>${rows.length?'':empty('No matching members','Try a different filter or add a family member.')}</div>`;}
function members(){const p=population(recs()),rows=recs('member').filter(m=>matchesMember(m,data.records,{search:query}));return `${pageHead(t('members'),'One record per person, across every stage of care.',btn('Add member','add-member','plus','primary'))}<div class="stats">${stat('Resident population',p.total,'Confirmed events included','users')}${stat('Male',p.Male,'Current residents','users')}${stat('Female',p.Female,'Current residents','users')}${stat('Other / unknown',p.Other+p.Unknown,'Included in the total','users')}</div><div class="toolbar">${searchBox('Search name, phone or ABHA…')}${btn('Export CSV','export-members','download')}</div>${memberTable(rows)}`;}
function care(){const preg=recs('pregnancy').filter(r=>r.data.status==='Active'),children=population(recs()).members.filter(m=>memberAge(m)!==null&&memberAge(m)<5);return `${pageHead(t('care'),'Pregnancy, newborn care and growing children.',btn('Register pregnancy','add-pregnancy','plus','primary'))}<div class="notice">Visit schedules come from locally approved templates in Settings. Clinical decisions and referrals remain with the authorised health team.</div><div class="page-head spacer"><h2>Active pregnancies</h2>${badge(preg.length+' records')}</div><div class="cards">${preg.map(p=>`<div class="family-card"><div class="row between"><span class="stat-icon">${icon('heart',20)}</span>${badge(p.data.risk||'Routine follow-up',p.data.risk==='Review requested'?'amber':'')}</div><h3>${esc(person(p.data.memberId))}</h3><p>Expected delivery · ${dateText(p.data.edd)}<br>Last menstrual period · ${dateText(p.data.lmp)}</p><div class="row wrap">${btn('Open record','edit-pregnancy','edit','sm',`data-id="${p.id}"`)}${btn('Member profile','open-member','arrow','ghost sm',`data-id="${p.data.memberId}"`)}</div></div>`).join('')||empty('No active pregnancies','Add a pregnancy to an existing member to start follow-up.')}</div><div class="page-head spacer"><h2>Children below 5</h2>${btn('Add child','add-member','plus','sm')}</div>${memberTable(children)}`;}
function visits(){let rows=recs('visit').filter(v=>person(v.data.memberId).toLowerCase().includes(query.toLowerCase()));if(visitFilter==='pending')rows=rows.filter(v=>v.data.status==='Planned');if(visitFilter==='overdue')rows=rows.filter(v=>visitState(v)==='Overdue');if(visitFilter==='completed')rows=rows.filter(v=>v.data.status==='Completed');rows.sort((a,b)=>a.data.dueDate.localeCompare(b.data.dueDate));return `${pageHead(t('visits'),'Plan your day. Record what happened. Keep follow-up visible.',btn('Plan visit','add-visit','plus','primary'))}<div class="tabs">${[['all','All visits'],['pending','Planned'],['overdue','Overdue'],['completed','Completed']].map(([v,l])=>`<button class="tab ${visitFilter===v?'active':''}" data-action="visit-filter" data-value="${v}">${l}</button>`).join('')}</div><div class="toolbar">${searchBox('Find a member’s visits…')}${badge(rows.length+' visits')}</div><div class="panel">${rows.length?visitRows(rows):empty('No visits in this view','Plan a visit or generate visits from an approved schedule.',btn('Plan visit','add-visit','plus','primary'))}</div>`;}
function lists(){const rows=recs('member').filter(m=>matchesMember(m,data.records,listFilter));return `${pageHead(t('lists'),'Find the people who need your attention.',btn('Export this list','export-list','download','primary'))}<div class="tabs">${[['under5','Children below 5'],['over80','Over 80 years'],['abha','ABHA not recorded'],['hypertension','Hypertension'],['diabetes','Diabetes'],['pregnancy','Pregnant women'],['all','All residents']].map(([v,l])=>`<button class="tab" data-action="preset" data-value="${v}">${l}</button>`).join('')}</div><form id="filters" class="filter-panel">${field('search','Name, phone or ABHA','search',listFilter.search||'')}${field('minAge','Minimum age','number',listFilter.minAge??'','min="0" max="125"')}${field('maxAge','Maximum age','number',listFilter.maxAge??'','min="0" max="125"')}${select('sex','Sex',[['','Any'],'Male','Female','Other','Unknown'],listFilter.sex||'')}${select('condition','Condition',[['','Any'],...CONDITIONS],listFilter.condition||'')}${select('abha','ABHA',[['','Any'],['missing','Not recorded']],listFilter.abha||'')}${select('residence','Residence',[['','Any'],'Resident','Temporary','Moved away','Deceased'],listFilter.residence||'')}<div class="row wrap">${btn('Apply filters','apply-filter','filter','primary')}${btn('Save list','save-list','plus','sm')}</div></form><div class="toolbar">${badge(`${rows.length} matching members`)}<span class="muted"><small>Confirmed condition filter · ages as of ${dateText(today())}</small></span>${data.savedLists?.length?select('saved-list','Saved lists',[['','Choose a saved list'],...data.savedLists.map((l,i)=>[i,l.name])]):''}</div>${memberTable(rows)}`;}
function reportSnapshot(month){const p=population(recs()),events=recs('event').filter(r=>r.data.date.startsWith(month)&&r.data.status==='Confirmed'),visits=recs('visit');return {generatedAt:new Date().toISOString(),populationAsOf:today(),residentPopulation:p.total,male:p.Male,female:p.Female,other:p.Other,unknown:p.Unknown,households:recs('household').length,childrenUnder5:p.under5,over80:p.over80,abhaNotRecorded:p.abhaMissing,activePregnancies:recs('pregnancy').filter(r=>r.data.status==='Active').length,births:events.filter(r=>r.data.type==='Birth').length,deaths:events.filter(r=>r.data.type==='Death').length,visitsDue:visits.filter(v=>v.data.dueDate.startsWith(month)).length,visitsCompleted:visits.filter(v=>v.data.status==='Completed'&&v.data.actualDate?.startsWith(month)).length,overdueAsOfToday:visits.filter(v=>visitState(v)==='Overdue').length,scope:ownerFilter?worker(ownerFilter):data.user.role==='admin'?'All managed ASHAs':data.user.name,lastSync:data.lastSync};}
function reports(){const month=data.reportMonth||today().slice(0,7),s=reportSnapshot(month);return `${pageHead(t('reports'),'Turn everyday records into a clear reporting draft.',btn('Save monthly report','save-report','file','primary'))}<div class="toolbar">${field('report-month','Activity month','month',month)}${btn('Download CSV','export-report','download')}${btn('Print / save PDF','print','file')}</div><p class="notice">Population is the current resident count as of ${dateText(s.populationAsOf)}. Births, deaths and visit activity use the selected month. Saved reports preserve a snapshot. Exports do not submit to a government portal.</p><div class="stats spacer">${stat('Resident population',s.residentPopulation,`${s.male} male · ${s.female} female · ${s.other+s.unknown} other / unknown`,'users')}${stat('Visits performed',s.visitsCompleted,`${s.visitsDue} visits due in ${month}`,'calendar')}${stat('Births recorded',s.births,'Confirmed events in this month','baby')}${stat('Deaths recorded',s.deaths,'Confirmed events in this month','file')}</div><section class="panel"><div class="panel-head"><h2>Saved reports</h2>${badge(recs('report').length+' reports')}</div><div class="table-scroll"><table><thead><tr><th>Report</th><th>Period</th><th>ASHA</th><th>Status</th><th></th></tr></thead><tbody>${recs('report').reverse().map(r=>`<tr><td>${esc(r.data.name)}</td><td>${esc(r.data.month)}</td><td>${esc(worker(r.ownerId))}</td><td>${badge(r.data.status,r.data.status==='Returned'?'red':r.data.status==='Submitted'?'amber':'')}</td><td>${btn('Review','open-report','arrow','sm',`data-id="${r.id}"`)}</td></tr>`).join('')}</tbody></table></div>${count('report')?'':empty('No reports saved yet','Save a draft, review its totals, then submit it to your supervisor.')}</section>`;}
function team(){return `${pageHead(t('team'),'Manage accounts and household assignments.',btn('Create ASHA account','add-user','plus','primary'))}<div class="cards">${data.users.map(u=>`<div class="family-card"><div class="row">${nameAvatar(u.name,'green')}<div><h3>${esc(u.name)}</h3><p>${esc(u.username)}</p></div></div><p>${esc(u.area)}</p><div class="row wrap">${badge(u.role==='admin'?'Administrator':'ASHA')}${badge(u.active===false?'Inactive':'Active',u.active===false?'red':'')}${badge(data.records.filter(r=>r.kind==='member'&&r.ownerId===u.id).length+' members','neutral')}</div>${u.id!==data.user.id?btn('Manage access','manage-user','settings','sm',`data-id="${u.id}"`):''}</div>`).join('')}</div><div class="notice spacer">Each ASHA can access their assigned records. Resetting a password or deactivating an account revokes its server sessions. Offline devices remain protected by their offline password.</div>`;}
function settings(){return `${pageHead(t('settings'),'Your workspace, records and care templates.')}<div class="settings-grid"><section class="panel setting-section"><h3>Workspace & language</h3><p>${esc(data.user.area)}<br>${demo?'Fictional demonstration':esc(serverBase)}</p>${btn(language==='en'?'हिन्दी navigation':'English navigation','language','globe')}${btn('Change sign-in password','password','lock','ghost spacer')}<p class="spacer">Core navigation is available in English and Hindi. Clinical form labels are currently English.</p></section><section class="panel setting-section"><h3>Offline records</h3><p>${demo?'Demo changes last for this session.':`${data.outbox.length} pending change(s). Last synced: ${data.lastSync?new Date(data.lastSync).toLocaleString('en-IN'):'Not yet'}.`}</p><div class="row wrap">${btn('Sync now','sync','sync','primary')}${btn('Lock workspace','lock','lock')}</div>${!demo?btn('Remove this device’s saved copy','remove-vault','','danger spacer'):''}</section><section class="panel setting-section"><h3>Approved visit schedules</h3><p>Define the programme, date offsets and approving health professional. Confirm current local HBNC, HBYC or SSBSK guidance before activation.</p>${data.user.role==='admin'?btn('Add approved schedule','add-schedule','plus'):''}<div class="spacer">${recs('schedule').map(s=>`<div class="record-row"><strong>${esc(s.data.name)}</strong><small>${esc(s.data.program)} · v${s.version} · ${s.data.active?'Active':'Inactive'}</small><small>${esc(s.data.offsets.join(', '))} ${esc(s.data.unit)} after birth / reference date</small>${data.user.role==='admin'?btn('Edit','edit-schedule','edit','ghost sm',`data-id="${s.id}"`):''}</div>`).join('')||'<small class="muted">No templates approved yet. Individual visits can still be planned.</small>'}</div></section><section class="panel setting-section"><h3>Accountability</h3><p>Saved changes, sign-ins and document downloads have an audit history. Reports and attachments follow the same area permissions as member records.</p>${data.user.role==='admin'?btn('View audit history','audit','shield'):''}<p class="spacer">ASHA Saathi is an independent application. It does not issue ABHA IDs, diagnoses or official birth/death certificates.</p></section></div>`;}
function render(){if(!data)return;const renderers={home,households,members,care,visits,lists,reports,team,settings};if(!renderers[view])view='home';
  const admin=data.user.role==='admin';if(view==='team'&&!admin)view='home';
  app.innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="#" data-action="nav-home"><img src="assets/logo.svg" alt="ASHA Saathi"><div><strong>ASHA Saathi</strong><small>Connected care</small></div></a><div class="workspace-tag">${icon('home',16)}<span>${esc(data.user.area)}</span></div><div class="eyebrow nav-label">WORKSPACE</div><nav class="nav">${navs.map(([k,i])=>`<button data-action="nav-${k}" class="${view===k?'active':''}">${icon(i,19)}${esc(t(k))}${k==='visits'&&recs('visit').filter(v=>visitState(v)==='Overdue').length?`<span class="nav-badge">${recs('visit').filter(v=>visitState(v)==='Overdue').length}</span>`:''}</button>`).join('')}</nav><div class="eyebrow nav-label">MANAGE</div><nav class="nav">${admin?`<button data-action="nav-team" class="${view==='team'?'active':''}">${icon('users',19)}${t('team')}</button>`:''}<button data-action="nav-settings" class="${view==='settings'?'active':''}">${icon('settings',19)}${t('settings')}</button></nav><div class="sidebar-bottom"><div class="sidebar-note">${icon('leaf',22)}<h3>Care, a little closer.</h3><p>Less paperwork. More time for your community.</p></div><div class="user-box row">${nameAvatar(data.user.name)}<div class="grow"><strong>${esc(data.user.name)}</strong><small class="muted">${admin?'Administrator':'ASHA worker'}</small></div><button class="btn ghost sm" data-action="lock" aria-label="Lock workspace">${icon('logout',17)}</button></div></div></aside><main class="main"><header class="topbar"><div class="row"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Open menu">${icon('menu',17)}</button><div class="breadcrumb">Workspace ${icon('chevron',12)} <strong>${esc(t(view))}</strong></div></div><div class="topbar-actions"><span class="connection"><span class="status-dot"></span>${demo?'Demo workspace':data.outbox.length?'Changes pending':token?'Connected':'Offline unlocked'}</span><button id="sync-button" class="btn sm" data-action="sync">${icon('sync',15)}Sync${data.outbox.length?' ('+data.outbox.length+')':''}</button><button class="icon-btn" data-action="language" aria-label="Change navigation language">${icon('globe',17)}</button>${nameAvatar(data.user.name)}</div></header><div class="content">${demo?`<div class="demo-strip">${icon('leaf',14)} <span>Demo workspace · All people and health records shown are fictional.</span><button data-action="lock">Connect server</button></div>`:''}${admin?`<div class="toolbar no-print"><span class="date-chip">${icon('calendar',14)}${dateText(today())}</span><div class="grow"></div><select id="owner-filter" aria-label="Filter by ASHA"><option value="">All managed ASHAs</option>${data.users.filter(u=>u.role==='asha').map(u=>`<option value="${u.id}" ${ownerFilter===u.id?'selected':''}>${esc(u.name)} · ${esc(u.area)}</option>`).join('')}</select></div>`:''}${renderers[view]()}</div></main><nav class="mobile-nav">${[['home','grid'],['households','home'],['visits','calendar'],['lists','filter'],['settings','settings']].map(([k,i])=>`<button data-action="nav-${k}" class="${view===k?'active':''}">${icon(i,21)}${esc(k==='home'?t('today'):t(k))}</button>`).join('')}</nav></div>`;
  $('#owner-filter')?.addEventListener('change',e=>{ownerFilter=e.target.value;render();});
  $('#page-search')?.addEventListener('input',e=>{query=e.target.value;const pos=e.target.selectionStart;render();$('#page-search')?.focus();$('#page-search')?.setSelectionRange(pos,pos);});
  $('#report-month')?.addEventListener('change',e=>{data.reportMonth=e.target.value;render();});
  $('#f-report-month')?.addEventListener('change',e=>{data.reportMonth=e.target.value;render();});
  $('#f-saved-list')?.addEventListener('change',e=>{if(e.target.value!==''){listFilter=data.savedLists[Number(e.target.value)].filter;render();}});
  $('#filters')?.addEventListener('submit',e=>{e.preventDefault();applyFilters();});renderSync();
}
function ownerSelect(value){return data.user.role==='admin'?select('ownerId','Assigned ASHA',data.users.filter(u=>u.role==='asha'&&u.active!==false).map(u=>[u.id,u.name]),value||ownerFilter):'';}
function memberSelect(selected){return select('memberId','Member',recs('member').map(m=>[m.id,`${m.data.name} · ${find(m.data.householdId)?.data.name||''}`]),selected,'required');}
function needMembers(){if(!count('member')){toast('Add a family and a member first.',true);return false;}return true;}
function householdForm(id){const r=id?find(id):null,d=r?.data||{};form(r?'Edit family':'Add a family',field('name','Family / household name','text',d.name,'required maxlength="200"')+field('locality','Village / ward / locality','text',d.locality,'required')+note('address','Address',d.address)+(r?'':ownerSelect())+field('contact','Contact number','tel',d.contact)+note('notes','Household notes',d.notes),async f=>{if(!f.address.trim())throw Error('Please enter an address.');const owner=r?.ownerId||f.ownerId||data.user.id;delete f.ownerId;await save('household',f,r,owner);});}
function openHousehold(id){const r=find(id),ms=recs('member').filter(m=>m.data.householdId===id);dialog(r.data.name,`<p class="muted">${esc(r.data.address)} · ${esc(r.data.locality)}</p><p class="muted"><small>Assigned to ${esc(worker(r.ownerId))}</small></p><div class="section-label"><h3>Family members</h3>${btn('Add member','add-member','plus','sm',`data-household="${id}"`)}</div>${ms.map(m=>`<div class="visit-row">${nameAvatar(m.data.name,'green')}<div class="grow"><strong>${esc(m.data.name)}</strong><p>${memberAge(m)??'Age unknown'}${m.data.dob?'':' ≈'} · ${esc(m.data.sex)} · ${esc(m.data.relationship||'Member')}</p></div>${btn('Open','open-member','chevron','ghost sm',`data-id="${m.id}"`)}</div>`).join('')||empty('No members yet','Add the people who live in this household.')}`,btn('Edit family','edit-household','edit','',`data-id="${id}"`)+(data.user.role==='admin'?btn('Transfer to ASHA','transfer','users','',`data-id="${id}"`):''));}
function memberForm(id,householdId){if(!count('household'))return toast('Create a family first.',true);const r=id?find(id):null,d=r?.data||{};form(r?'Edit member':'Add a family member',select('householdId','Family',recs('household').filter(h=>!r||h.ownerId===r.ownerId).map(h=>[h.id,h.data.name]),d.householdId||householdId,'required')+field('name','Full name','text',d.name,'required maxlength="200"')+select('sex','Sex',['Unknown','Female','Male','Other'],d.sex||'Unknown')+field('dob','Date of birth, if known','date',d.dob,`max="${today()}"`)+field('estimatedAge','Estimated age, if DOB unknown','number',d.estimatedAge??'','min="0" max="125"')+field('relationship','Relationship in family','text',d.relationship)+field('phone','Phone, if available','tel',d.phone)+field('abha','ABHA number, optional','text',d.abha,'inputmode="numeric" maxlength="17"')+select('abhaStatus','ABHA status',['Not recorded','Recorded, unverified','Verified externally','Not created (reported)','Declined assistance'],d.abhaStatus||'Not recorded')+select('residence','Residence',['Resident','Temporary','Moved away','Deceased'],d.residence||'Resident')+field('registeredOn','Resident registration date','date',d.registeredOn||today(),`required max="${today()}"`)+note('notes','Notes',d.notes),async f=>{if(f.dob&&f.dob>today())throw Error('Date of birth cannot be in the future.');if(f.abha&&!/^\d{14}$/.test(f.abha.replaceAll('-','').replaceAll(' ','')))throw Error('ABHA should contain 14 digits.');if(f.dob)f.estimatedAge='';f.ageRecordedOn=d.ageRecordedOn||today();await save('member',f,r,find(f.householdId).ownerId);},{description:'An ABHA number, phone number or document is not required. Keep an uncertain date of birth blank and enter an estimated age instead.'});}
function openMember(id){const m=find(id),d=m.data,related=data.records.filter(r=>r.data.memberId===id),conditions=related.filter(r=>r.kind==='condition'),documents=related.filter(r=>r.kind==='document'),events=related.filter(r=>r.kind==='event');dialog(d.name,`<div class="row">${nameAvatar(d.name,'green')}<div><h3>${esc(find(d.householdId)?.data.name||'')}</h3><small class="muted">${esc(worker(m.ownerId))}</small></div></div><dl class="details-grid">${[['Age',`${memberAge(m)??'Unknown'}${d.dob?'':' (estimated / unknown)'}`],['Date of birth',dateText(d.dob)],['Sex',d.sex],['Residence',residence(m,data.records)],['ABHA',d.abha?`•••• •••• ••${d.abha.slice(-4)} · ${d.abhaStatus}`:'Not recorded'],['Phone',d.phone||'Not recorded']].map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><div class="row wrap">${btn('Plan visit','add-visit','calendar','sm',`data-member="${id}"`)}${btn('Pregnancy','add-pregnancy','heart','sm',`data-member="${id}"`)}${btn('Generate visits','generate-visits','sync','sm',`data-id="${id}"`)}</div><div class="section-label"><h3>Conditions</h3>${btn('Add condition','add-condition','plus','sm',`data-member="${id}"`)}</div>${conditions.map(c=>`<div class="record-row row between"><div><strong>${esc(c.data.name)}</strong><small>${esc(c.data.status)} · ${esc(c.data.source)}</small></div>${btn('Edit','edit-condition','edit','ghost sm',`data-id="${c.id}"`)}</div>`).join('')||'<p class="muted"><small>No conditions recorded.</small></p>'}<div class="section-label"><h3>Documents</h3>${btn('Upload','add-document','upload','sm',`data-member="${id}"`)}</div>${documents.map(doc=>`<div class="record-row row between"><div class="file-name"><strong>${esc(doc.data.name)}</strong><small>${esc(doc.data.category)} · ${Math.ceil((doc.data.size||0)/1024)} KB</small></div>${btn('Download','download-document','download','ghost sm',`data-id="${doc.id}"`)}</div>`).join('')||'<p class="muted"><small>No documents attached.</small></p>'}<div class="section-label"><h3>Birth, death & movement</h3>${btn('Add event','add-event','plus','sm',`data-member="${id}"`)}</div>${events.map(e=>`<div class="record-row row between"><div><strong>${esc(e.data.type)} · ${dateText(e.data.date)}</strong><small>${esc(e.data.status)} · ${esc(e.data.source)}</small></div>${btn('Edit','edit-event','edit','ghost sm',`data-id="${e.id}"`)}</div>`).join('')||'<p class="muted"><small>No events recorded.</small></p>'}<div class="section-label"><h3>Visits</h3></div>${related.some(r=>r.kind==='visit')?visitRows(related.filter(r=>r.kind==='visit').sort((a,b)=>b.data.dueDate.localeCompare(a.data.dueDate)).slice(0,6)):'<p class="muted"><small>No visits recorded.</small></p>'}`,btn('Edit member','edit-member','edit','',`data-id="${id}"`));}
function pregnancyForm(id,memberId){if(!needMembers())return;const r=id?find(id):null,d=r?.data||{};form(r?'Pregnancy record':'Register pregnancy',memberSelect(d.memberId||memberId)+field('registeredOn','Registration date','date',d.registeredOn||today(),`required max="${today()}"`)+field('lmp','Last menstrual period, if known','date',d.lmp,`max="${today()}"`)+field('edd','Expected delivery date','date',d.edd)+select('status','Pregnancy status',['Active','Delivered','Miscarriage','Stillbirth','Other outcome'],d.status||'Active')+select('risk','Recorded follow-up priority',['Routine follow-up','Review requested','Clinician-documented high risk'],d.risk||'Routine follow-up')+field('source','Date / risk information source','text',d.source)+note('notes','Care notes and referrals',d.notes),async f=>{if(f.lmp&&f.edd&&f.edd<f.lmp)throw Error('Expected delivery must be after the last menstrual period.');await save('pregnancy',f,r,find(f.memberId).ownerId);},{description:'Record dates and risk information from the person or clinical record. Each pregnancy has its own history. After a live birth, add the newborn to the family and record a birth event.'});}
function conditionForm(id,memberId){if(!needMembers())return;const r=id?find(id):null,d=r?.data||{};form(r?'Update condition':'Record a condition',memberSelect(d.memberId||memberId)+select('name','Condition',CONDITIONS,d.name||'Hypertension')+select('status','Evidence status',['Suspected','Self-reported','Confirmed','Resolved'],d.status||'Self-reported')+field('date','Date recorded / diagnosed','date',d.date||today(),`required max="${today()}"`)+field('source','Source of information','text',d.source,'required placeholder="e.g. clinic report or person’s account"')+note('notes','Follow-up notes and referral',d.notes),f=>save('condition',f,r,find(f.memberId).ownerId),{description:'Screening or a single measurement does not establish a diagnosis. Keep suspected and self-reported conditions distinct from documented confirmed cases.'});}
function visitForm(id,memberId){if(!needMembers())return;const r=id?find(id):null,d=r?.data||{};form(r?'Visit record':'Plan a visit',memberSelect(d.memberId||memberId)+select('program','Programme',['HBNC','HBYC','SSBSK','ANC','PNC','Immunisation','NCD','TB','Referral','Other'],d.program||'HBNC')+field('dueDate','Scheduled date','date',d.dueDate||today(),'required')+select('status','Visit status',['Planned','Completed','Attempted','Declined','Transferred','Cancelled'],d.status||'Planned')+field('actualDate','Actual visit date','date',d.actualDate,`max="${today()}"`)+field('vaccine','Vaccine / dose, if applicable','text',d.vaccine)+field('referral','Referral / facility, if applicable','text',d.referral)+select('referralStatus','Referral follow-up',['Not applicable','Pending','Attended','Outcome recorded'],d.referralStatus||'Not applicable')+note('notes','Observations, counselling, source and outcome',d.notes)+`<div class="field full"><label>Visit documentation</label>${['Contact or attempted contact recorded','Relevant records reviewed','Counselling / actions documented','Follow-up / referral recorded'].map((l,i)=>`<label class="check"><input name="check-${i}" type="checkbox" ${d.checklist?.includes(i)?'checked':''}>${l}</label>`).join('')}</div>`,async f=>{if(['Completed','Attempted'].includes(f.status)&&!f.actualDate)throw Error('Enter the actual date of the visit.');if(f.status==='Cancelled'&&!f.notes.trim())throw Error('Enter a cancellation reason.');f.checklist=[0,1,2,3].filter(i=>f[`check-${i}`]);for(let i=0;i<4;i++)delete f[`check-${i}`];await save('visit',f,r,find(f.memberId).ownerId);},{description:'Use your locally approved clinical form for care and danger-sign assessment. These checkboxes document the activity; they are not a clinical assessment tool.'});}
function eventForm(id,memberId){if(!needMembers())return;const r=id?find(id):null,d=r?.data||{};form(r?'Review an event':'Record a birth, death or move',memberSelect(d.memberId||memberId)+select('type','Event',['Birth','Death','Arrival','Departure'],d.type||'Birth')+field('date','Event date','date',d.date||today(),`required max="${today()}"`)+select('status','Verification status',['Reported','Confirmed','Voided'],d.status||'Reported')+field('source','Source / report reference','text',d.source,'required')+note('notes','Details / reason for correction',d.notes),async f=>{if(f.type==='Birth'&&data.records.some(e=>e.kind==='event'&&e.id!==id&&e.data.memberId===f.memberId&&e.data.type==='Birth'&&e.data.status!=='Voided'))throw Error('This member already has a birth event. Edit the existing record.');if(f.status==='Voided'&&!f.notes.trim())throw Error('Record why this event is being voided.');await save('event',f,r,find(f.memberId).ownerId);},{description:'For a newborn, first create or link the child’s member record. Confirmed deaths and departures adjust resident totals; records are retained. An app entry does not issue or register an official certificate.'});}
function documentForm(memberId){if(!needMembers())return;form('Attach a document',memberSelect(memberId)+select('category','Document type',['Birth report','Death report','Clinical report','Immunisation record','Identity / ABHA','Other'])+`<div class="field full"><label for="f-file">Photo or PDF, up to 5 MB</label><input id="f-file" type="file" name="file" accept="application/pdf,image/png,image/jpeg,image/webp" required></div>`+note('notes','Document note'),async(f,element)=>{const file=element.elements.file.files[0];if(!file||file.size>5*1024*1024)throw Error('Choose an image or PDF up to 5 MB.');const content=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});delete f.file;await save('document',{...f,name:file.name,mime:file.type,content,size:file.size},null,find(f.memberId).ownerId);},{description:'Attach only documents needed for care or reporting. Files are encrypted with the offline workspace and uploaded during sync.'});}
function scheduleForm(id){const r=id?find(id):null,d=r?.data||{};form(r?'Edit approved schedule':'Add approved visit schedule',field('name','Template name','text',d.name,'required')+select('program','Programme',['HBNC','HBYC','SSBSK','ANC','PNC','Other'],d.program||'HBNC')+select('unit','Offsets measured in',['days','months'],d.unit||'days')+field('offsets','Offsets after the reference date','text',d.offsets?.join(', '),'required placeholder="Use values from the approved guideline"')+field('effectiveDate','Effective from','date',d.effectiveDate||today(),'required')+field('approvedBy','Approved by / designation','text',d.approvedBy,'required')+field('source','Guideline title and version','text',d.source,'required')+select('active','Template status',[['true','Active'],['false','Inactive']],String(d.active??false)),async f=>{f.offsets=f.offsets.split(',').map(s=>Number(s.trim()));if(f.offsets.some(n=>!Number.isInteger(n)||n<0||n>1200)||f.offsets.length>50)throw Error('Enter up to 50 valid offsets separated by commas.');f.active=f.active==='true';await save('schedule',f,r,data.user.id);},{description:'Enter the schedule approved by your local health team. No historical national schedule is activated automatically. Updating a template does not silently rewrite completed visits.'});}
function generateVisits(memberId){const m=find(memberId),templates=recs('schedule').filter(s=>s.data.active);if(!templates.length)return toast('An administrator needs to add an approved visit schedule in Settings first.',true);form('Generate scheduled visits',select('scheduleId','Approved template',templates.map(s=>[s.id,`${s.data.name} · v${s.version}`]))+field('anchor','Birth / programme reference date','date',m.data.dob||'','required'),async f=>{const schedule=find(f.scheduleId),values=scheduleVisits(m,schedule,data.records.filter(r=>r.kind==='visit'),f.anchor);for(const v of values)await save('visit',v,null,m.ownerId);toast(`${values.length} visits created. Existing matching visits were kept.`);},{description:'Review the template and reference date. Past planned dates will appear as overdue, not completed.'});}
function applyFilters(){const f=Object.fromEntries(new FormData($('#filters')));if(f.minAge!==''&&f.maxAge!==''&&Number(f.minAge)>Number(f.maxAge))return toast('Minimum age must not exceed maximum age.',true);listFilter={...f,pregnant:listFilter.pregnant||false};render();}
function filteredRows(){return recs('member').filter(m=>matchesMember(m,data.records,view==='lists'?listFilter:{search:query}));}
async function download(name,mime,content){const blob=content instanceof Blob?content:new Blob([content],{type:mime});if(window.AndroidDownloads){const base64=await new Promise(resolve=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.readAsDataURL(blob);});window.AndroidDownloads.saveFile(name,mime,base64);return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),20000);}
async function logExport(name){if(!demo&&token)await api('/api/export-log',{method:'POST',body:JSON.stringify({name})}).catch(()=>{});}
async function exportMembers(){const rows=filteredRows(),name=`ASHA-Saathi-${view}-${today()}.csv`;await logExport(name);await download(name,'text/csv;charset=utf-8',toCSV([['ASHA Saathi','Generated',today(),'Filter',JSON.stringify(view==='lists'?listFilter:{search:query})],['Name','Family','Age','Age certainty','Sex','Residence','ABHA status','ASHA'],...rows.map(m=>[m.data.name,find(m.data.householdId)?.data.name,memberAge(m),m.data.dob?'DOB recorded':'Estimated / unknown',m.data.sex,residence(m,data.records),m.data.abhaStatus||'Not recorded',worker(m.ownerId)])]));}
async function exportReport(snapshotValue,month){const name=`ASHA-Saathi-report-${month}.csv`;await logExport(name);await download(name,'text/csv;charset=utf-8',toCSV([['ASHA Saathi monthly activity report',month],['Metric','Value'],...Object.entries(snapshotValue)]));}
function openReport(id){const r=find(id),s=r.data.snapshot;dialog(r.data.name,`<p class="muted">${esc(r.data.month)} · ${esc(worker(r.ownerId))} · ${badge(r.data.status)}</p><dl class="details-grid">${Object.entries(s).map(([k,v])=>`<div><dt>${esc(k.replace(/([A-Z])/g,' $1'))}</dt><dd>${esc(v??'Not recorded')}</dd></div>`).join('')}</dl>${r.data.reviewNote?`<p class="notice">${esc(r.data.reviewNote)}</p>`:''}`,btn('Export snapshot','export-snapshot','download','',`data-id="${id}"`)+(r.data.status==='Draft'||r.data.status==='Returned'?btn('Submit','submit-report','check','primary',`data-id="${id}"`):'')+(data.user.role==='admin'&&r.data.status==='Submitted'?btn('Review','review-report','shield','primary',`data-id="${id}"`):''));}
function changePassword(){if(demo)return toast('Password changes are available in a connected workspace.');form('Change sign-in password',field('currentPassword','Current / temporary password','password','','required autocomplete="current-password"')+field('newPassword','New password, 12+ characters','password','','required minlength="12" autocomplete="new-password"'),async f=>{const result=await api('/api/password',{method:'POST',body:JSON.stringify(f)});data.user=result.user;await persist();setTimeout(sync,50);toast('Password updated.');},{description:'This changes your server sign-in password. Your device’s offline encryption password stays the same.'});}
async function lock(){if(syncing)return toast('Please let the current sync finish before locking.');if(data&&!demo){await persist();if(token)api('/api/logout',{method:'POST',body:'{}'}).catch(()=>{});}modal.close();await renderLogin();}
document.addEventListener('click',async e=>{
  const target=e.target.closest('[data-action]');if(!target)return;const action=target.dataset.action,id=target.dataset.id,memberId=target.dataset.member;
  try{
    if(action.startsWith('nav-')){e.preventDefault();view=action.slice(4);query='';modal.close();render();window.scrollTo(0,0);return;}
    if(action==='close'){modal.close();return;}
    if(action==='demo'){demo=true;data=demoWorkspace();token='';view='home';ownerFilter='';render();return;}
    if(action==='language'){language=language==='en'?'hi':'en';localStorage.setItem('asha-language',language);document.documentElement.lang=language;render();return;}
    if(action==='lock'){await lock();return;}
    if(action==='menu'){$('.sidebar').classList.toggle('open');return;}
    if(action==='setup'){form('Set up your workspace',field('server','Server address','url',serverBase,'required placeholder="https://your-server.example"')+field('setupToken','One-time setup token','password','','required')+field('name','Administrator name','text','','required')+field('area','Service area / organisation','text','','required')+field('username','Administrator username','text','','required minlength="3"')+field('password','Administrator password','password','','required minlength="12" autocomplete="new-password"'),async f=>{setServer(f.server);delete f.server;await api('/api/setup',{method:'POST',body:JSON.stringify(f)});toast('Workspace created. Sign in with your new administrator account.');},{label:'Create workspace',description:'Your server operator can find the one-time token in the data/bootstrap-token file. No default administrator password is included.'});return;}
    if(action==='unlock'){const meta=await vault.metadata();if(!meta)throw Error('No saved workspace found.');form('Unlock offline workspace',field('password','Offline password','password','','required'),async f=>{data=await vault.unlock(f.password);demo=false;token='';serverBase=meta.server;view='home';toast('Offline workspace unlocked. Sign in again to sync.');},{label:'Unlock',description:`Saved for ${meta.user.name}. ${meta.pending} change(s) waiting to sync.`});return;}
    if(!data)return;
    if(action==='sync'){await sync();return;}
    if(action==='add-household'||action==='edit-household'){householdForm(id);return;}
    if(action==='open-household'){openHousehold(id);return;}
    if(action==='add-member'||action==='edit-member'){memberForm(id,target.dataset.household);return;}
    if(action==='open-member'){openMember(id);return;}
    if(action==='add-pregnancy'||action==='edit-pregnancy'){pregnancyForm(id,memberId);return;}
    if(action==='add-condition'||action==='edit-condition'){conditionForm(id,memberId);return;}
    if(action==='add-visit'||action==='edit-visit'){visitForm(id,memberId);return;}
    if(action==='add-event'||action==='edit-event'){eventForm(id,memberId);return;}
    if(action==='add-document'){documentForm(memberId);return;}
    if(action==='add-schedule'||action==='edit-schedule'){scheduleForm(id);return;}
    if(action==='generate-visits'){generateVisits(id);return;}
    if(action==='visit-filter'){visitFilter=target.dataset.value;render();return;}
    if(action==='preset'){listFilter={residence:'Resident',...({under5:{maxAge:4},over80:{minAge:81},abha:{abha:'missing'},hypertension:{condition:'Hypertension'},diabetes:{condition:'Diabetes'},pregnancy:{pregnant:true},all:{}}[target.dataset.value])};render();return;}
    if(action==='apply-filter'){applyFilters();return;}
    if(action==='save-list'){applyFilters();form('Save this smart list',field('name','List name','text','','required'),async f=>{data.savedLists??=[];data.savedLists.push({name:f.name,filter:structuredClone(listFilter)});await persist();toast('Saved on this device.');});return;}
    if(action==='export-list'||action==='export-members'){await exportMembers();return;}
    if(action==='export-report'){const month=data.reportMonth||today().slice(0,7);await exportReport(reportSnapshot(month),month);return;}
    if(action==='print'){await logExport('Print monthly report');if(window.AndroidDownloads?.printPage)window.AndroidDownloads.printPage();else window.print();return;}
    if(action==='save-report'){const month=data.reportMonth||today().slice(0,7),snapshotValue=reportSnapshot(month);form('Save monthly report',field('name','Report name','text',`${month} — ${ownerFilter?worker(ownerFilter):data.user.name}`,'required'),f=>save('report',{...f,month,status:'Draft',snapshot:snapshotValue,scopeOwnerId:ownerFilter||null},null,data.user.id));return;}
    if(action==='open-report'){openReport(id);return;}
    if(action==='export-snapshot'){const r=find(id);await exportReport(r.data.snapshot,r.data.month);return;}
    if(action==='submit-report'){await save('report',{status:'Submitted'},find(id));modal.close();render();return;}
    if(action==='review-report'){const r=find(id);form('Review monthly report',select('status','Decision',['Accepted','Returned'])+note('reviewNote','Review note'),f=>save('report',f,r));return;}
    if(action==='password'){changePassword();return;}
    if(action==='add-user'){form('Create ASHA account',field('name','Full name','text','','required')+field('area','Assigned service area','text','','required')+field('username','Username','text','','required minlength="3"')+field('password','Temporary password, 12+ characters','password','','required minlength="12" autocomplete="new-password"')+select('role','Role',[['asha','ASHA worker'],['admin','Administrator']]),async f=>{if(demo){data.users.push({id:crypto.randomUUID(),...f,password:undefined,active:true,mustChangePassword:true});toast('Demo account added.');}else{const r=await api('/api/users',{method:'POST',body:JSON.stringify(f)});data.users.push(r.user);await persist();toast('Account created. Share the temporary password securely.');}},{description:'The worker must change their temporary password when they first sign in.'});return;}
    if(action==='manage-user'){const u=data.users.find(x=>x.id===id);form(`Manage ${u.name}`,select('active','Account access',[['true','Active'],['false','Inactive']],String(u.active!==false))+field('password','New temporary password, optional','password','','minlength="12" autocomplete="new-password"'),async f=>{f.active=f.active==='true';if(!f.password)delete f.password;if(demo){Object.assign(u,{active:f.active});return;}const r=await api(`/api/users/${id}`,{method:'PATCH',body:JSON.stringify(f)});data.users=data.users.map(x=>x.id===id?r.user:x);await persist();},{description:'Resetting a password or deactivating access ends this worker’s server sessions. Their records stay intact.'});return;}
    if(action==='transfer'){const h=find(id);form('Transfer household assignment',select('ownerId','Receiving ASHA',data.users.filter(u=>u.role==='asha'&&u.active!==false&&u.id!==h.ownerId).map(u=>[u.id,u.name]))+note('reason','Transfer reason'),async f=>{if(!f.ownerId||!f.reason.trim())throw Error('Select an ASHA and enter a reason.');if(data.outbox.length)throw Error('Sync pending changes before transferring a household.');if(demo){const memberIds=new Set(data.records.filter(r=>r.kind==='member'&&r.data.householdId===id).map(r=>r.id));for(const r of data.records)if(r.id===id||memberIds.has(r.id)||memberIds.has(r.data.memberId)){r.ownerId=f.ownerId;r.version++;}}else{await api('/api/transfer',{method:'POST',body:JSON.stringify({...f,householdId:id})});await sync();}toast('Household and related care records transferred.');},{description:'This transfers the household, its members and their care records. Existing report snapshots remain with their original author.'});return;}
    if(action==='download-document'){const d=find(id);let blob;if(d.data.content){blob=new Blob([Uint8Array.from(atob(d.data.content),c=>c.charCodeAt(0))],{type:d.data.mime});}else{if(!token)throw Error('Sign in to download this document from the server.');const response=await fetch(`${serverBase}/api/documents/${id}`,{headers:{Authorization:`Bearer ${token}`}});if(!response.ok)throw Error('Could not download this document.');blob=await response.blob();}await download(d.data.name,d.data.mime,blob);return;}
    if(action==='audit'){const rows=demo?[{at:new Date().toISOString(),actor:'demo-admin',action:'demo.open',target:'Fictional workspace'}]:(await api('/api/audit')).entries;dialog('Recent audit history',`<div class="table-scroll"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Record</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(new Date(r.at).toLocaleString())}</td><td>${esc(worker(r.actor))}</td><td>${esc(r.action)}</td><td>${esc(r.target)}</td></tr>`).join('')}</tbody></table></div>`);return;}
    if(action==='remove-vault'){if(data.outbox.length)throw Error('Sync all pending changes before removing the saved copy.');form('Remove saved device copy',field('confirmation','Type REMOVE to confirm','text','','required'),async f=>{if(f.confirmation!=='REMOVE')throw Error('Type REMOVE to confirm.');await vault.remove();data=null;token='';setTimeout(renderLogin,0);},{label:'Remove device copy',description:'This removes the encrypted cache from this device. Records already synced to the server are retained.'});return;}
    if(action==='conflict-server'||action==='conflict-local'){const {mutation:m,saved}=conflict;if(action==='conflict-server'){data.outbox=data.outbox.filter(x=>x.id!==m.id);data.records=data.records.filter(r=>r.id!==m.id);if(saved)data.records.push(saved);}else{if(!saved)throw Error('The saved record is unavailable. Contact your supervisor.');const local=data.outbox.find(x=>x.id===m.id);local.baseVersion=saved.version;local.mutationId=crypto.randomUUID();}conflict=null;await persist();modal.close();render();await sync();return;}
  }catch(error){toast(error.message||'Could not complete this action.',true);}
});
let hiddenAt=0;
document.addEventListener('visibilitychange',()=>{if(document.hidden)hiddenAt=Date.now();else if(hiddenAt&&Date.now()-hiddenAt>120000&&data&&!demo)lock();});
window.addEventListener('online',()=>{if(data&&!demo&&token)sync();});
if('serviceWorker' in navigator&&location.hostname!=='appassets.androidplatform.net')navigator.serviceWorker.register('./sw.js').catch(()=>{});
await renderLogin();
